<?php
namespace Database\Seeders;
use App\Models\{User,PartnerProfile,FoodCategory,FoodDonation,FoodRequest,Reservation,DeliveryTask}; use Illuminate\Database\Seeder; use Illuminate\Support\Facades\Hash;
class DatabaseSeeder extends Seeder { public function run(): void { $admin=User::create(['full_name'=>'Admin User','email'=>'admin@foodlink.test','password_hash'=>Hash::make('password'),'role'=>'ADMIN','account_status'=>'ACTIVE']); $donor=User::create(['full_name'=>'Donor Partner','email'=>'donor@foodlink.test','password_hash'=>Hash::make('password'),'role'=>'FOOD_DONOR','account_status'=>'ACTIVE']); $charity=User::create(['full_name'=>'Charity Partner','email'=>'charity@foodlink.test','password_hash'=>Hash::make('password'),'role'=>'CHARITY','account_status'=>'ACTIVE']); $volunteer=User::create(['full_name'=>'Volunteer Rider','email'=>'volunteer@foodlink.test','password_hash'=>Hash::make('password'),'role'=>'VOLUNTEER','account_status'=>'ACTIVE']); $donorP=PartnerProfile::create(['user_id'=>$donor->user_id,'address'=>'12 Donor Street','verification_status'=>'APPROVED']); $charityP=PartnerProfile::create(['user_id'=>$charity->user_id,'address'=>'45 Charity Avenue','verification_status'=>'APPROVED']); $volP=PartnerProfile::create(['user_id'=>$volunteer->user_id,'address'=>'78 Volunteer Road','verification_status'=>'APPROVED']); foreach([['Rice','Staple food'],['Vegetables','Fresh produce'],['Bakery','Bread and pastries'],['Canned Food','Shelf-stable items']] as $c) FoodCategory::create(['category_name'=>$c[0],'description'=>$c[1]]); $cat=FoodCategory::first(); $donation=FoodDonation::create(['donor_id'=>$donorP->profile_id,'category_id'=>$cat->category_id,'food_name'=>'Cooked Rice Packs','description'=>'Freshly prepared surplus rice packs.','donation_quantity'=>50,'current_quantity'=>40,'measurement_unit'=>'packs','expiry_datetime'=>now()->addDay(),'pickup_address'=>'12 Donor Street','storage_type'=>'Room temperature','halal_status'=>'Halal','donation_status'=>'AVAILABLE']); $request=FoodRequest::create(['charity_id'=>$charityP->profile_id,'category_id'=>$cat->category_id,'requested_quantity'=>20,'fulfilled_quantity'=>10,'unit'=>'packs','request_deadline'=>now()->addDays(2),'request_status'=>'OPEN']); $reservation=Reservation::create(['request_id'=>$request->request_id,'donation_id'=>$donation->donation_id,'reserved_quantity'=>10,'reservation_status'=>'CONFIRMED','pickup_deadline'=>now()->addDay()]); DeliveryTask::create(['reservation_id'=>$reservation->reservation_id,'volunteer_id'=>$volP->profile_id,'pickup_address'=>$donation->pickup_address,'delivery_address'=>$charityP->address,'delivery_status'=>'ASSIGNED']); } }
